"""Use case: ask for a Studio output; it is generated by a background job (§ 3.4.0)."""

from collections.abc import Mapping
from typing import Any
from uuid import UUID

from app.modules.notebooks.application.access import load_notebook
from app.modules.notebooks.application.artifact_cache import (
    key_for_request,
    served_from_cache,
)
from app.modules.notebooks.application.artifact_engine import (
    clean_prompt,
    common_options,
    fresh_estimate,
    kick_generation,
    pipeline_shape,
    queued_artifact,
    reserved,
)
from app.modules.notebooks.application.budget import NotebookBudget
from app.modules.notebooks.application.locale import LocaleResolver
from app.modules.notebooks.application.quota import QuotaService
from app.modules.notebooks.domain.artifacts.registry import (
    handler_for,
    supported_kinds,
)
from app.modules.notebooks.domain.entities import Artifact, Notebook, Source
from app.modules.notebooks.domain.enums import ArtifactKind
from app.modules.notebooks.domain.errors import (
    ArtifactLimitError,
    FeatureDisabledError,
    InvalidOptionsError,
    NoSourcesSelectedError,
)
from app.modules.notebooks.domain.language import resolve_language
from app.modules.notebooks.domain.web_suggestion import suggestion_for_request
from app.modules.notebooks.ports.unit_of_work import NotebooksUnitOfWork, UowFactory
