from pydantic import BaseModel


def _kind_of(kind: ArtifactKind | str) -> ArtifactKind:
    """Check that this build can generate the kind.

    Raises:
        FeatureDisabledError: Audio overview (not built, by decision).
        InvalidOptionsError: Any other kind that does not exist.
    """
    try:
        known = ArtifactKind(kind)
    except ValueError:
        raise InvalidOptionsError(
            params={"details": [f"kind: unknown kind {str(kind)[:40]}"]},
            support_details="unknown kind",
        ) from None
    if known is ArtifactKind.AUDIO_OVERVIEW:
        raise FeatureDisabledError(params={"feature": known.value})
    if known not in supported_kinds():
        raise InvalidOptionsError(
            params={"details": [f"kind: {known.value} is not supported"]},
            support_details="unsupported kind",
        )
    return known


def _require_workspace_for(kind: ArtifactKind, notebook: Notebook) -> None:
    """Course plans and lesson drafts exist only in a course workspace.

    Raises:
        InvalidOptionsError: The notebook is a student's own notebook.
    """
    if kind.is_course_kind and not notebook.is_course_workspace:
        raise InvalidOptionsError(
            params={"details": [f"kind: {kind.value} needs a course workspace"]},
            support_details="course kind outside a course workspace",
        )


class RequestArtifact:
    """Validates a request, counts it against the limits and queues the job."""

    def __init__(
        self,
        *,
        uow_factory: UowFactory,
        budget: NotebookBudget,
        quota: QuotaService,
        kicker: TaskKicker,
        clock: Clock,
        settings: Settings,
        locale: LocaleResolver,
    ) -> None:
        """Store the collaborators."""
        self.uow_factory = uow_factory
        self.budget = budget
        self.quota = quota
        self.kicker = kicker
        self.clock = clock
        self.settings = settings
        self.locale = locale

    async def execute(
        self,
        actor: Actor,
        notebook_id: UUID,
        kind: ArtifactKind | str,
        options: Mapping[str, Any],
        prompt: str | None,
    ) -> Artifact:
        """Insert a `queued` output and start its job; return the new row.

        If another student already got the same output (same texts, kind, options and
        language, no custom focus), the student gets a copy of it at once: `ready`,
        no model call, no budget, quota or "generating" slot used.

        Raises:
            NotebookNotFoundError: Not the student's notebook.
            FeatureDisabledError: Audio overview is not built.
            InvalidOptionsError: Unknown kind, wrong options or a bad focus text.
            NoSourcesSelectedError: Sources are picked, but none is ready.
            ArtifactLimitError: The notebook already holds the maximum of outputs.
            LimitReachedError: The weighted-token budget is used up.
            QuotaExceededError: The daily count of the kind is used up.
            BusyError: Too many outputs are generating already.
        """
        known = _kind_of(kind)
        handler = handler_for(known)
        async with self.uow_factory() as uow:
            notebook = await load_notebook(
                uow, actor.user_id, notebook_id, for_update=True
            )
            _require_workspace_for(known, notebook)
            parsed = handler.parse_options(dict(options))
            focus = clean_prompt(prompt)
            handler.task_block(parsed, focus)  # rejects e.g. a custom report
            sources = await self._pick_sources(uow, notebook, parsed)
            await self._ensure_room(uow, notebook)
            stored_options = handler.stored_options(parsed)
            language = resolve_language(
                common_options(parsed).language,
                await self.locale.locale_of(actor.user_id),
            )
            if known.is_course_kind:  # the requester's language, not the owner's
                stored_options.setdefault("language", language)
            key = key_for_request(
                kind=known,
                report_format=handler.report_format(parsed),
                options=stored_options,
                prompt=focus,
                sources=sources,
                language=language,
            )
            if notebook.is_course_workspace or not sources:
                key = None  # a course context makes it unique, no sources: no sharing
            hit = await self._hit(uow, notebook, key, sources, stored_options)
            if hit is not None:
                await uow.artifacts.add(hit)
                await uow.commit()
                return hit
            estimate = fresh_estimate(
                handler,
                parsed,
                sources,
                self.settings.notebooks.studio_context_tokens,
                pipeline_shape(known, parsed, self.settings),
            )
            course = notebook.is_course_workspace
            await self.budget.pool(course).require(actor.user_id, estimate)
            artifact = queued_artifact(
                notebook=notebook,
                kind=known,
                title=handler.default_title(notebook.title, parsed),
                options=stored_options,
                prompt=focus,
                source_ids=[source.id for source in sources],
                source_map={f"S{n}": str(s.id) for n, s in enumerate(sources, start=1)},
                now=self.clock.now(),
                report_format=handler.report_format(parsed),
            )
            artifact.cache_key = key
            artifact.suggest_web_search = suggestion_for_request(
                char_counts=[source.char_count for source in sources],
                title=notebook.title,
                focus=focus,
                threshold=self.settings.notebooks.thin_sources_chars,
            )
            if course:  # a shared notebook: the staff member who asked pays
                artifact.requested_by = actor.user_id
            quota = self.quota.pool(course)
            async with reserved(quota, actor.user_id, known, artifact.id):
                await uow.artifacts.add(artifact)
                kick_generation(uow, self.kicker, artifact.id)
                await uow.commit()
        return artifact

    async def _hit(
        self,
        uow: NotebooksUnitOfWork,
        notebook: Notebook,
        key: str | None,
        sources: list[Source],
        options: dict[str, Any],
    ) -> Artifact | None:
        """A `ready` copy of an output another student already got, if there is one."""
        if key is None:
            return None
        now = self.clock.now()
        entry = await uow.shared.get_artifact(key, now)
        if entry is None:
            return None
        return served_from_cache(
            entry=entry, notebook=notebook, sources=sources, options=options, now=now
        )

    async def _pick_sources(
        self, uow: NotebooksUnitOfWork, notebook: Notebook, options: BaseModel
    ) -> list[Source]:
        """The ready sources of the request: the given ids, else the selection.

        Nothing selected gives an empty list: the output is made without sources.
        """
        wanted = set(common_options(options).source_ids or [])
        sources = await uow.sources.list_for_notebook(notebook.id)
        chosen = [
            source
            for source in sources
            if source.usable and (source.id in wanted if wanted else source.selected)
        ]
        if not chosen and (wanted or any(source.selected for source in sources)):
            raise NoSourcesSelectedError()  # asked for, or picked but not ready
        return chosen

    async def _ensure_room(self, uow: NotebooksUnitOfWork, notebook: Notebook) -> None:
        """At most `max_artifacts` outputs per notebook."""
        limit = self.settings.notebooks.max_artifacts
        if await uow.artifacts.count_live(notebook.id) >= limit:
            raise ArtifactLimitError(params={"limit": limit})
